from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.cell_unlock.classical_cell_unlock.cell_unlock_prototype import CellUnlock
from taf.ul.kpi_selector.operations.cell_unlock.classical_cell_unlock.cell_unlock_23R1 import CellUnlock23R1


class CellUnlockFactory(OperationFactoryPrototype):
    def __init__(self):
        super(CellUnlockFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for cell unlock operation.
        :return: dictionary with timeout, requirement and operation description for cell unlock
        :rtype: dict
        """
        if self.bts.stream >= "SBTS23R1":
            return CellUnlock23R1(self.bts).get_kpi()
        else:
            return CellUnlock(self.bts).get_kpi()
